import { test, expect } from '@playwright/test';

test.describe('Accessibility - Colour Contrast', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('Check text color contrast against background', async ({ page }) => {
    const textElement = page.getByText('Sample Text'); // Replace with actual text
    const backgroundColor = await page.evaluate(element => {
      return window.getComputedStyle(element).backgroundColor;
    }, textElement);

    const textColor = await page.evaluate(element => {
      return window.getComputedStyle(element).color;
    }, textElement);

    const contrastRatio = calculateContrastRatio(textColor, backgroundColor);
    expect(contrastRatio).toBeGreaterThanOrEqual(4.5); // AA standard for normal text
  });

  test('Check button color contrast', async ({ page }) => {
    const buttonElement = page.getByRole('button', { name: 'Submit' }); // Replace with actual button name
    const backgroundColor = await page.evaluate(element => {
      return window.getComputedStyle(element).backgroundColor;
    }, buttonElement);

    const textColor = await page.evaluate(element => {
      return window.getComputedStyle(element).color;
    }, buttonElement);

    const contrastRatio = calculateContrastRatio(textColor, backgroundColor);
    expect(contrastRatio).toBeGreaterThanOrEqual(3.0); // AA standard for large text
  });
});

